class Checkout
  FREE_SHIPPING_FROM = 100_00

  def initialize(country:)
    @country = country
    @items = []
  end

  def add_item(price_cents)
    @items << price_cents
  end

  def subtotal
    @items.sum
  end

  def shipping
    return 0 if @country == "DE" && subtotal >= FREE_SHIPPING_FROM

    5_00
  end

  def total
    subtotal + shipping
  end
end

class Checkout
  def initialize(gateway:)
    @gateway = gateway
  end

  def complete(order)
    @gateway.charge(order.total_cents)
    OrderMailer.receipt(order).deliver_later
  end
end

class Order
  def initialize
    @items = []
  end

  def add_item(price_cents)
    @items << price_cents
  end

  def total_cents
    @items.sum
  end
end
